/**
 * Bundled per-ship upgrade chains + ship-level research economy, generated by
 * `scripts/extract/build_upgrade_chain.py` (one bundle per realm, the same
 * WG/Lesta split the ships view's realm switch uses).
 *
 *   - `ship_upgrade_chain.json`         WG snapshot (`wg-<build>`)
 *   - `ship_upgrade_chain_lesta.json`   Lesta snapshot (`lesta-<build>`)
 *
 * Each ship record carries the ship-level economy straight from GameParams'
 * ShipUpgradeInfo scalars (`costXP` = XP to research the ship from its
 * predecessor, `costCR` = port price, `costGold` = doubloon price), the
 * module slots as stock -> top `prev` chains (per-ucType brackets, mirroring
 * shipParts.ts' chainsByKind resolution) with the components each module
 * mounts, and the ships the module research unlocks (already resolved from
 * GameParams entry keys to numeric shipIds). Every step also carries its raw
 * `prev` prerequisite key (null for stock) and its upgrade `depth` inside the
 * slot — same-level alternatives share a depth, so the panel can lay parallel
 * variants out side by side.
 *
 * The client's module economy (per-module research XP + buy credits, and the
 * "with required modules" research total) is not in GameParams: it arrives in
 * the server-synced price catalog the in-game probe captures. Every step
 * therefore carries `gpid` (the module's numeric GameParams id, the catalog's
 * join key) and the xp/credits/xpWithModules/requiredModules fields, which
 * stay null until `scripts/extract/apply_price_catalog.py` applies a capture
 * to the bundle. The tech-tree tooltip's minimal case reads `next[xpShip]`
 * (the next ship's own costXP) and grows a "with required modules" row the
 * moment `xpWithModules` is filled.
 */
import chainWgRaw from "@/data/ship_upgrade_chain.json";
import chainLestaRaw from "@/data/ship_upgrade_chain_lesta.json";
import type { TechTreeRealm } from "./techTreeData";

/** Component-role map of one module step ("hull" -> ["A_Hull"], ...). */
export type UpgradeComponents = Record<string, string[]>;

/** Ship-level research/buy economy (ShipUpgradeInfo costXP / costCR / costGold). */
export interface UpgradeResearch {
  /** XP needed to research the ship from its predecessor. */
  xp: number;
  /** Credits to buy the ship in port. */
  credits: number;
  /** Doubloon price (premiums; 0 for tech-tree ships). */
  gold: number;
}

/** One ship this ship unlocks, keyed by the unlocked ship's numeric id. */
export interface UpgradeNextShip {
  /** The unlocked ship's GameParams index ("PRSD308"). */
  index: string | null;
  /** The NEXT ship's own costXP — the minimal research-tooltip value. */
  xpShip: number | null;
  /** Ship XP + the required modules' research XP; null until a price
   *  catalog capture is applied (or when a required module's XP is missing). */
  xpWithModules: number | null;
  /** GameParams names of the modules that must be researched for the unlock. */
  requiredModules: string[] | null;
}

/** One module step of a slot's stock -> top chain. */
export interface UpgradeStep {
  /** GameParams upgrade entry name ("PRUH603_D7_HULL_STOCK_2"). */
  name: string;
  /** Numeric GameParams entity id of the module entry — the key the client's
   *  server-synced price catalog uses, so a captured price_catalog.json joins
   *  straight onto the step. Null on slice/bundle-fallback generations. */
  gpid: number | null;
  /** True for the slot's stock module — the first (top-left) step. */
  isStock: boolean;
  /** GameParams upgrade entry key this module upgrades from; null for stock. */
  prev: string | null;
  /** Upgrade level inside the slot: stock = 0; same-level alternatives share it. */
  depth: number;
  /** Per-module research XP (from a captured price catalog), else null. */
  xp: number | null;
  /** Per-module buy credits (from a captured price catalog), else null. */
  credits: number | null;
  /** Component-role map this module mounts (component NAMES, not blocks). */
  components: UpgradeComponents;
  /** Numeric shipIds this module's research unlocks; absent when none. */
  unlocks?: number[];
}

/** One module bracket (ucType slot), steps ordered by upgrade depth (stock -> top). */
export interface UpgradeSlot {
  /** Raw GameParams ucType ("_Hull", "_Suo", "_Torpedoes", ...). */
  ucType: string;
  steps: UpgradeStep[];
}

/** One ship's upgrade chain + research economy. */
export interface ShipUpgradeChain {
  index: string;
  research: UpgradeResearch;
  /** Unlocked ships keyed by stringified shipId. */
  next: Record<string, UpgradeNextShip>;
  slots: UpgradeSlot[];
}

/** One realm's generated bundle. */
export interface ShipUpgradeChainBundle {
  gameVersion: string;
  source: string;
  ships: Record<string, ShipUpgradeChain>;
}

const CHAINS: Record<TechTreeRealm, ShipUpgradeChainBundle> = {
  wg: chainWgRaw as ShipUpgradeChainBundle,
  lesta: chainLestaRaw as ShipUpgradeChainBundle,
};

/** Every ship chain of a realm, keyed by stringified shipId. */
export function allUpgradeChains(
  realm: TechTreeRealm = "wg",
): Record<string, ShipUpgradeChain> {
  return CHAINS[realm].ships;
}

/** One ship's chain in a realm, or null when that realm's snapshot lacks it. */
export function shipUpgradeChain(
  shipId: number,
  realm: TechTreeRealm = "wg",
): ShipUpgradeChain | null {
  return CHAINS[realm].ships[String(shipId)] ?? null;
}

/** The realm bundle's gameVersion stamp ("wg-13357625" / "lesta-8867689"). */
export function upgradeChainGameVersion(realm: TechTreeRealm = "wg"): string {
  return CHAINS[realm].gameVersion;
}

/** Ship-level research economy (costXP / costCR / costGold), or null. */
export function researchOf(
  shipId: number,
  realm: TechTreeRealm = "wg",
): UpgradeResearch | null {
  return shipUpgradeChain(shipId, realm)?.research ?? null;
}

/** The research data for the edge fromShipId -> toShipId, or null when absent. */
export function nextResearch(
  fromShipId: number,
  toShipId: number,
  realm: TechTreeRealm = "wg",
): UpgradeNextShip | null {
  return shipUpgradeChain(fromShipId, realm)?.next[String(toShipId)] ?? null;
}
